mapper.select:
SELECT
FROM goods_spu spu
LEFT JOIN ship_goods_profile profile ON profile.spu_id = spu.id AND profile.tenant_id = spu.tenant_id AND profile.del_flag = '0' LEFT JOIN goods_sku sku ON sku.spu_id = spu.id AND sku.tenant_id = spu.tenant_id AND sku.del_flag = '0' LEFT JOIN ship_sku_profile sku_profile ON sku_profile.sku_id = sku.id AND sku_profile.tenant_id = spu.tenant_id AND sku_profile.del_flag = '0' WHERE spu.tenant_id = #{tenantId} AND spu.del_flag = '0'
AND profile.sale_scope = #{query.saleScope}
AND (profile.impa_code LIKE CONCAT('%', #{query.keyword}, '%') OR profile.issa_code LIKE CONCAT('%', #{query.keyword}, '%') OR profile.internal_item_code LIKE CONCAT('%', #{query.keyword}, '%') OR profile.barcode LIKE CONCAT('%', #{query.keyword}, '%') OR profile.name_en LIKE CONCAT('%', #{query.keyword}, '%') OR spu.name LIKE CONCAT('%', #{query.keyword}, '%') OR profile.search_aliases LIKE CONCAT('%', #{query.keyword}, '%'))
AND (profile.impa_code LIKE CONCAT('%', #{query.impaCode}, '%') OR profile.issa_code LIKE CONCAT('%', #{query.impaCode}, '%') OR profile.internal_item_code LIKE CONCAT('%', #{query.impaCode}, '%') OR profile.barcode LIKE CONCAT('%', #{query.impaCode}, '%'))
AND (profile.name_en LIKE CONCAT('%', #{query.nameEn}, '%') OR spu.name LIKE CONCAT('%', #{query.nameEn}, '%') OR profile.search_aliases LIKE CONCAT('%', #{query.nameEn}, '%'))
AND profile.storage_type = #{query.storageType}
AND spu.`status` = #{query.status}
AND sku_profile.moq >= #{query.moq}
AND profile.publish_completeness <= #{query.publishCompleteness}
ORDER BY spu.create_time DESC
